suppressPackageStartupMessages({library(Seurat);library(Matrix);library(harmony);library(jsonlite);library(ggplot2)})
root<-Sys.getenv('PROJECT_ROOT');stopifnot(nchar(root)>0)
r<-file.path(root,'annotation_rebuild/20261105_v7_literature_guided_reannotation_v1');out<-file.path(r,'stage_k_T6_source_robust_diagnostic_v1/fit');stopifnot(!dir.exists(out));dir.create(out)
started<-format(Sys.time(),tz='UTC',usetz=TRUE);set.seed(20261105)
write_json(list(status='running_initial_T6_diagnostic',UTC_start=started,scope='All frozen T6 cells; no Treg reference prefilter'),file.path(out,'started.json'),pretty=TRUE)
counts<-Read10X_h5(file.path(r,'stage_j_T6_fullgene/T6_v7_fullgene_raw_10x.h5'),use.names=TRUE,unique.features=TRUE)
meta<-read.delim(gzfile(file.path(r,'stage_j_T6_fullgene/T6_v7_metadata_PRIVATE.tsv.gz')),row.names=1,check.names=FALSE,stringsAsFactors=FALSE)
stopifnot(ncol(counts)==156631,nrow(counts)==95038,identical(colnames(counts),rownames(meta)))
original_gene<-rownames(counts);feature_id<-original_gene;unsafe<-grepl('_|\\|',original_gene);feature_id[unsafe]<-paste0('V7FEATURE',which(unsafe));stopifnot(!anyDuplicated(feature_id));rownames(counts)<-feature_id
gene_map<-data.frame(feature_id=feature_id,gene_symbol=original_gene);write.table(gene_map,file.path(out,'feature_id_gene_symbol_map.tsv'),sep='\t',quote=FALSE,row.names=FALSE)
obj<-CreateSeuratObject(counts=counts,meta.data=meta,min.cells=0,min.features=0,project='V7_T6_targeted_diagnostic')
obj<-NormalizeData(obj,normalization.method='LogNormalize',scale.factor=10000,verbose=FALSE)
features<-read.delim(file.path(r,'stage_k_T6_source_robust_diagnostic_v1/source_robust_model_genes.tsv'),stringsAsFactors=FALSE)$gene_symbol
features<-feature_id[match(features,original_gene)];stopifnot(!anyNA(features),!anyDuplicated(features))
obj[['HVG_source_robust']]<-CreateAssayObject(counts=GetAssayData(obj,assay='RNA',layer='counts')[features,,drop=FALSE])
obj<-FindVariableFeatures(obj,assay='HVG_source_robust',selection.method='vst',nfeatures=2000,verbose=FALSE);hvg<-VariableFeatures(obj[['HVG_source_robust']]);VariableFeatures(obj[['RNA']])<-hvg;DefaultAssay(obj)<-'RNA'
write.table(data.frame(feature_id=hvg,gene_symbol=original_gene[match(hvg,feature_id)]),file.path(out,'HVG_source_robust.tsv'),sep='\t',quote=FALSE,row.names=FALSE)
obj<-ScaleData(obj,assay='RNA',features=hvg,verbose=FALSE);obj<-RunPCA(obj,assay='RNA',features=hvg,npcs=50,seed.use=20261105,verbose=FALSE)
obj<-FindNeighbors(obj,reduction='pca',dims=1:30,graph.name=c('raw_nn','raw_snn'),verbose=FALSE);obj<-FindClusters(obj,graph.name='raw_snn',resolution=.4,random.seed=20261105,verbose=FALSE)
obj<-RunHarmony(obj,group.by.vars='gse_id',reduction.use='pca',dims.use=1:30,reduction.save='harmony_source',project.dim=FALSE,verbose=FALSE)
obj<-FindNeighbors(obj,reduction='harmony_source',dims=1:30,graph.name=c('source_nn','source_snn'),verbose=FALSE);res<-c(.2,.4,.6,.8)
obj<-FindClusters(obj,graph.name='source_snn',resolution=res,random.seed=20261105,verbose=FALSE)
obj<-RunUMAP(obj,reduction='harmony_source',dims=1:30,reduction.name='umap_source',reduction.key='UMAPsource_',seed.use=20261105,verbose=FALSE)
md<-obj[[]];cols<-grep('^(raw|source)_snn_res',colnames(md),value=TRUE)
summary<-do.call(rbind,lapply(cols,function(cn){z<-table(md[[cn]]);data.frame(graph=cn,cluster=names(z),n_cells=as.integer(z))}));write.table(summary,file.path(out,'cluster_resolution_counts.tsv'),sep='\t',quote=FALSE,row.names=FALSE)
source_summary<-do.call(rbind,lapply(cols,function(cn){z<-table(md[[cn]],md$gse_id);data.frame(graph=cn,cluster=rownames(z),n_cells=rowSums(z),n_gse=rowSums(z>0),max_gse_fraction=apply(z,1,max)/rowSums(z))}));write.table(source_summary,file.path(out,'cluster_source_concentration.tsv'),sep='\t',quote=FALSE,row.names=FALSE)
Idents(obj)<-'source_snn_res.0.4';DefaultAssay(obj)<-'RNA'
markers<-FindAllMarkers(obj,assay='RNA',slot='data',min.pct=.1,min.diff.pct=.25,logfc.threshold=.25,return.thresh=.01,only.pos=FALSE,test.use='wilcox',verbose=FALSE)
markers$feature_id<-markers$gene;markers$gene<-original_gene[match(markers$feature_id,feature_id)];stopifnot(!anyNA(markers$gene));write.table(markers,file.path(out,'RNA_FindAllMarkers_source_res0.4.tsv'),sep='\t',quote=FALSE,row.names=FALSE)
write.table(cbind(cell_id=rownames(md),md),gzfile(file.path(out,'metadata_PRIVATE.tsv.gz')),sep='\t',quote=FALSE,row.names=FALSE)
panels<-list('T identity'=c('CD3D','CD3E','TRAC'),'CD4 context'=c('CD4'),'CD8 context'=c('CD8A','CD8B'),'Treg candidate'=c('FOXP3','IKZF2','IL2RA'),'Treg activation state'=c('CTLA4','TNFRSF4','TIGIT','CCR8','TNFRSF9'),'Naive-memory state'=c('CCR7','TCF7','LEF1','IL7R'),'Tfh-Tph candidate'=c('BCL6','CXCR5','CXCL13','ICOS'),'Th17 candidate'=c('RORC','CCR6','KLRB1'),'Th1-cytotoxic shared'=c('TBX21','IFNG','NKG7','GNLY','GZMK'),'Cycling state'=c('MKI67','TOP2A'),'IFN state'=c('ISG15','IFIT1'),'B competitor'=c('MS4A1','CD79A'),'Myeloid competitor'=c('LST1','CSF1R'),'Epithelial competitor'=c('EPCAM','KRT18'))
panels<-lapply(panels,function(g)intersect(g,rownames(obj)));obj$working_cluster_display<-paste0('T6 C',md$source_snn_res.0.4,' (annotation pending)')
pdf(file.path(out,'T6_initial_diagnostic.pdf'),width=18,height=9);print(ElbowPlot(obj,ndims=50));print(DimPlot(obj,reduction='umap_source',group.by='source_snn_res.0.4',label=TRUE,raster=TRUE));print(DimPlot(obj,reduction='umap_source',group.by='gse_id',raster=TRUE)+NoLegend());print(DotPlot(obj,features=panels,group.by='working_cluster_display')+RotatedAxis()+ggtitle('Marker targets are candidate identities / states; source measurement coverage is reviewed separately'));dev.off()
saveRDS(obj,file.path(out,'T6_source_robust_seurat_PRIVATE.rds'),compress=FALSE)
write_json(list(status='completed_T6_source_robust_initial_diagnostic',UTC_start=started,UTC_end=format(Sys.time(),tz='UTC',usetz=TRUE),n_cells=ncol(obj),n_RNA_features=nrow(obj[['RNA']]),n_HVG=length(hvg),n_model_feature_candidates=length(features),n_PCA=50,graph_PCs=30,source_covariate='gse_id; source sensitivity, not verified Technology',resolutions=res,marker_resolution=.4,normalization='Full-library RNA LogNormalize 10000',regressed_variables=character(),reference_labels_used_in_fit=FALSE,new_final_annotation_changes=0),file.path(out,'complete.json'),auto_unbox=TRUE,pretty=TRUE)
